 function pdfFixture(label){
  const content='BT /F1 14 Tf 60 375 Td (SOCLE V5 - PLAN DEVELOPPE - '+label+') Tj ET\n0.8 w 60 68 300 252 re S\n120 220 30 60 re S\nBT /F1 12 Tf 160 337 Td (10.00 m) Tj ET\nBT /F1 10 Tf 75 250 Td (4.20 m developpes) Tj ET\n';
  const objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R 6 0 R] /Count 2 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 600 400] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>','<< /Length '+Buffer.byteLength(content)+' >>\nstream\n'+content+'endstream','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 600 400] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>'];
  let text='%PDF-1.4\n',offsets=[0];for(let j=0;j<objects.length;j++){offsets.push(Buffer.byteLength(text));text+=(j+1)+' 0 obj\n'+objects[j]+'\nendobj\n'}const xref=Buffer.byteLength(text);text+='xref\n0 '+(objects.length+1)+'\n0000000000 65535 f \n'+offsets.slice(1).map(o=>String(o).padStart(10,'0')+' 00000 n \n').join('')+'trailer\n<< /Size '+(objects.length+1)+' /Root 1 0 R >>\nstartxref\n'+xref+'\n%%EOF';return Buffer.from(text);
 }
